"""Render an experiment report (dict) as Markdown. Numbers are reported as obtained."""

from __future__ import annotations

from typing import Any

DISCLAIMER = (
    "All results are on **synthetic data** generated by Sentinel's own simulator. They "
    "demonstrate methodology and do not estimate real-world fraud detection performance."
)
ORDER = ["rules_v1", "rules_tuned", "logreg", "random_forest", "isolation_forest", "hybrid"]


def _pct(x: float | None) -> str:
    return "—" if x is None else f"{100 * x:.1f}%"


def _num(x: float | None, digits: int = 3) -> str:
    return "—" if x is None else f"{x:.{digits}f}"


def _ci(ci: list[float], pct: bool = False) -> str:
    lo, hi = ci
    return f"[{_pct(lo)}, {_pct(hi)}]" if pct else f"[{lo:.3f}, {hi:.3f}]"


def render_report(r: dict[str, Any]) -> str:
    names = [n for n in ORDER if n in r["test"]]
    b = r["budget_per_1000"]
    sel = r["selection"]["selected"]
    out = [
        f"# Experiment report — `{r['dataset_version']}`",
        "",
        f"> {DISCLAIMER}",
        "",
        f"Alert budget: **{b:g} alerts per 1,000 transactions**. Thresholds were chosen on "
        "validation; test was evaluated once. Models trained on the *observed* label. "
        f"Feature schema `{r['feature_schema_hash']}` ({r['n_features']} inputs). "
        f"Runtime {r['runtime_seconds']:.0f}s.",
        "",
        "| Split | Transactions | Labelled fraud | Injected fraud |",
        "|---|--:|--:|--:|",
        *(
            f"| {k} | {v['n']:,} | {v['labelled_fraud']} | {v['injected_fraud']} |"
            for k, v in r["splits"].items()
        ),
        "",
        "## Test results (evaluated once)",
        "",
        "| Candidate | PR-AUC [95% CI] | ROC-AUC | Recall @ budget [95% CI] | Precision | "
        "Alerts / 1k | FP / 1k | Value detected | Brier |",
        "|---|---|--:|---|--:|--:|--:|--:|--:|",
    ]
    for n in names:
        t = r["test"][n]
        m, ci = t["at_budget"], t["ci95"]
        mark = " **(selected)**" if n == sel else ""
        out.append(
            f"| `{n}`{mark} | {_num(m['pr_auc'])} {_ci(ci['pr_auc'])} | {_num(m['roc_auc'])} | "
            f"{_pct(m['recall'])} {_ci(ci['recall'], True)} | {_pct(m['precision'])} | "
            f"{m['alerts_per_1000']:.1f} | {m['fp_per_1000']:.1f} | "
            f"{_pct(m.get('value_detection_rate'))} | {_num(m.get('brier'), 4)} |"
        )
    out += [
        "",
        "Recall against the *injected* ground truth (includes fraud that was never labelled):",
        "",
        "| Candidate | Recall (labelled) | Recall (injected) | "
        "F1-optimal threshold: precision / recall |",
        "|---|--:|--:|---|",
        *(
            f"| `{n}` | {_pct(r['test'][n]['at_budget']['recall'])} | "
            f"{_pct(r['test'][n]['against_injected_truth']['recall'])} | "
            f"{_pct(r['test'][n]['at_f1']['precision'])} / "
            f"{_pct(r['test'][n]['at_f1']['recall'])} |"
            for n in names
        ),
        "",
        "## Validation (used for every decision)",
        "",
        "| Candidate | PR-AUC | Recall @ budget | Precision @ budget | Alerts / 1k |",
        "|---|--:|--:|--:|--:|",
        *(
            f"| `{n}` | {_num(r['validation'][n]['at_budget']['pr_auc'])} | "
            f"{_pct(r['validation'][n]['at_budget']['recall'])} | "
            f"{_pct(r['validation'][n]['at_budget']['precision'])} | "
            f"{r['validation'][n]['at_budget']['alerts_per_1000']:.1f} |"
            for n in names
        ),
        "",
        f"Selection order (recall at budget, then PR-AUC): "
        f"{' > '.join(f'`{n}`' for n in r['selection']['ranking_on_validation'])}. "
        f"**Selected: `{sel}`.**",
        "",
        f"Hybrid: tuned rules + `{r['hybrid']['model']}` with w_rule = {r['hybrid']['w_rule']}, "
        f"w_model = {r['hybrid']['w_model']} (chosen on validation from "
        f"{', '.join(str(x['w_rule']) for x in r['hybrid']['log'])}).",
        "",
        "## Customer-disjoint holdout",
        "",
        "Customers never seen in training, at the validation thresholds.",
        "",
        "| Candidate | PR-AUC | Recall | Precision | Alerts / 1k |",
        "|---|--:|--:|--:|--:|",
        *(
            f"| `{n}` | {_num(r['holdout'][n]['pr_auc'])} | {_pct(r['holdout'][n]['recall'])} | "
            f"{_pct(r['holdout'][n]['precision'])} | {r['holdout'][n]['alerts_per_1000']:.1f} |"
            for n in names
        ),
        "",
        "## Seed variance",
        "",
        "| Model | Seeds | Validation PR-AUC | Test PR-AUC | Test recall @ budget |",
        "|---|--:|---|---|---|",
    ]
    for fam, v in r["seed_variance"].items():
        s = v["summary"]
        out.append(
            f"| `{fam}` | {len(v['per_seed'])} | "
            + " | ".join(
                f"{s[k]['mean']:.3f} ± {s[k]['std']:.3f}"
                for k in ("validation_pr_auc", "test_pr_auc", "test_recall_at_budget")
            )
            + " |"
        )
    out += ["", "## Error analysis (test, against injected ground truth)", ""]
    for name, ea in r["error_analysis"].items():
        out += [
            f"### `{name}`",
            "",
            "| Typology | Fraud transactions | Caught | Recall |",
            "|---|--:|--:|--:|",
            *(
                f"| `{k}` | {v['positives']} | {v['caught']} | {_pct(v['recall'])} |"
                for k, v in ea["recall_by_typology"].items()
            ),
            "",
            "| False positives by scenario | Legitimate txns | False positives | FP rate |",
            "|---|--:|--:|--:|",
            *(
                f"| {k} | {v['total']:,} | {v['count']} | {_pct(v['fp_rate'])} |"
                for k, v in ea["false_positives_by_benign_scenario"].items()
            ),
            "",
            "Missed fraud by amount (ZAR): "
            + ", ".join(
                f"{k}: {v['count']}/{v['total']}"
                for k, v in ea["false_negatives_by_amount_zar"].items()
            )
            + ". By customer history (prior 90-day transactions): "
            + ", ".join(
                f"{k}: {v['count']}/{v['total']}"
                for k, v in ea["false_negatives_by_history"].items()
            )
            + ". Unlabelled fraud caught: "
            + f"{ea['unlabelled_fraud_caught']}/{ea['unlabelled_fraud_total']}.",
            "",
        ]
    d = r["rule_model_disagreement"]
    out += [
        f"## Rules vs `{d['model']}` (test, at each one's budget threshold)",
        "",
        "| | Both | Rules only | Model only | Neither |",
        "|---|--:|--:|--:|--:|",
        *(
            f"| {k} | {v['both']} | {v['rules_only']} | {v['model_only']} | {v['neither']:,} |"
            for k, v in d["test"].items()
        ),
        "",
        "## Rule tuning (validation only)",
        "",
        "Recommended parameter changes (to be applied in the app as audited rule versions): "
        + (
            ", ".join(
                f"`{code}` {p}" for code, p in r["rule_tuning"]["recommended_changes"].items()
            )
            or "none"
        )
        + ".",
        "",
        "| Rule | v1 hit rate (validation) |",
        "|---|--:|",
        *(
            f"| `{k}` | {_pct(v)} |"
            for k, v in sorted(
                r["rule_tuning"]["hit_rates_validation_v1"].items(), key=lambda kv: -kv[1]
            )
        ),
        "",
        "## Leakage check (training split)",
        "",
        f"Best single-feature PR-AUC: `{r['leakage_check']['top'][0]['feature']}` = "
        f"{r['leakage_check']['top'][0]['pr_auc']:.3f} (prevalence "
        f"{r['leakage_check']['prevalence']:.4f}). Suspicious (> 0.95): "
        f"{', '.join(r['leakage_check']['suspicious']) or 'none'}.",
        "",
        "## Hyperparameters (TimeSeriesSplit, training period only)",
        "",
        *(
            f"- `{fam}`: selected {v['selected']} — "
            + "; ".join(f"{x['params']} → {x['cv_pr_auc_mean']:.3f}" for x in v["log"])
            for fam, v in r["hyperparameter_tuning"].items()
        ),
        "",
        "## Artefacts",
        "",
        *(f"- `{k}`: `{v['version']}`" for k, v in r["artefacts"].items()),
        "",
    ]
    return "\n".join(out)
